# Shown only from the second extraction of a window on: what the earlier extraction already states and leaves unstated.
CONTINUATION_PARAGRAPH = (
    '\nThis {text} has been extracted before. The context lists the fields your earlier extraction already stated '
    '(already_stated_fields) and the fields it left unavailable (not_yet_stated_fields). Give the complete answer again, '
    'keeping the same value, unit, quote and support for every field you already stated, and look through the {text} once more '
    'only for the fields not yet stated: state one only when the {text} itself says it. If the {text} states none of them, '
    'repeat your answer unchanged; nothing more can be extracted from this {text}.')


def extraction_instructions(experiment_type, *, text, reading='', continuing=False):
    """The instructions of one extraction: the type's instructions, the episode's own ``reading`` sentence ('' for none; it
    starts with a newline), the quote rule, the identity paragraph and, when ``continuing`` (the text was extracted before),
    the continuation paragraph. Every '{text}' of the library's texts is ``text``, the name of what the episode reads."""
    return (INSTRUCTIONS[experiment_type].format(text=text) + reading + QUOTE_UNIQUENESS.format(text=text)
            + IDENTITY_PARAGRAPH.format(text=text) + (CONTINUATION_PARAGRAPH.format(text=text) if continuing else ''))


def answer_schema(experiment_type):
    """The schema the model fills for ``experiment_type``: the type form's answer schema plus the identity block."""
    return identity.answer_schema_with_identity(FORMS[experiment_type].answer_schema())


def extraction_request(experiment_type, content, feedback, already_stated, not_yet_stated, *, text, reading=''):
    """The model request of one extraction of ``content`` (the text the episode reads, shown in the context under the key
    ``text``): ``feedback`` is why the previous answer was rejected (None at first); when ``already_stated`` (the fields the
    standing record of this text states) is not empty the request continues an earlier extraction and also shows
    ``not_yet_stated``."""
    context = {'experiment_type': experiment_type, text: content, 'previous_answer_was_rejected_because': feedback}
    continuing = bool(already_stated)
    if continuing:
        context['already_stated_fields'] = already_stated
        context['not_yet_stated_fields'] = not_yet_stated
    return ModelRequest('REASONING', extraction_instructions(experiment_type, text=text, reading=reading, continuing=continuing),
                        context, generation_schema(answer_schema(experiment_type)))


def extraction_call(response, experiment_type, content, *, source_ref, offset, limit, assertion_ref):
    """The ``extract`` call of the model's ``response`` to an extraction of ``content`` (the window ``offset``, ``limit`` of the
    source ``source_ref``): the answer is checked with the type form's validator and the identity validator (every quote found
    once in ``content``); a refused answer raises ``Rejected`` with the reason, before any unit exists."""
    form = FORMS[experiment_type]
    answer, identity_answer = identity.split_answer(decode_response(response, answer_schema(experiment_type)))
    try:
        form.validate_answer(answer, content)
        identity.validate_identity_answer(identity_answer, content)
    except (form.ExtractionRefused, identity.IdentityRefused) as refusal:
        raise Rejected({'status': 'invalid', 'category': 'extraction_refused', 'detail': str(refusal)})
    return ToolCall('extract', {'experiment_type': experiment_type, 'answer': answer, 'identity': identity_answer,
                                'source_ref': source_ref, 'chunk': content, 'offset': offset, 'limit': limit,
                                'assertion_ref': assertion_ref})



# The first choice of a leaf on one window: which methods the window reports. The page has not read the text, so it hands the
# leaf the relation the claim states only; the leaf names the methods (types of the classes that list it, or none) and then fills each one's form.
METHOD_INSTRUCTIONS = (
    'You are the first step of a system that scores how well published experiments support a proposed annotation of a '
    'protein. You are given one {text} of text from a published source and the relation the claim states (claim_predicate, for example binds or catalyzes). '
    'Say which experimental methods, if any, the {text} reports. The methods that can support such a claim are '
    'listed in methods, each with one plain line that says what it is.\n'
    'Answer with the list of every listed method that the {text} itself reports a result obtained with (a measured or '
    'stated value, or how the experiment was done), each method once, or with an empty list when the {text} reports none '
    'of the listed methods. A {text} that reports results of two or three methods names all of them. A method that the '
    '{text} only mentions as background, cites from other work or proposes for later is not reported and is not '
    'named. You extract nothing now: a later step reads the {text} again and fills in the form of each method you name.')


def methods_of(claim_predicate):
    """{experiment type: its plain line} of the types that can support a claim with ``claim_predicate`` (the types of every
    class that lists it), in registry order; a predicate with no type raises."""
    types = experiment_types_of_predicate(claim_predicate)
    if not types:
        raise ValueError('literature_claim_predicate_has_no_experiment_type:' + claim_predicate)
    return {name: EXPERIMENT_TYPE_LINES[name] for name in types}


def method_schema(claim_predicate):
    """The schema of the naming: one field, ``methods``, the list of the types of the class the text reports (empty: none)."""
    return {'type': 'object', 'additionalProperties': False, 'required': ['methods'],
            'properties': {'methods': {'type': 'array', 'items': {'type': 'string', 'enum': list(methods_of(claim_predicate))}}}}


def method_request(claim_predicate, content, feedback, *, text):
    """The model request that names the methods ``content`` (the text, shown under the key ``text``) reports."""
    context = {'claim_predicate': claim_predicate, 'methods': methods_of(claim_predicate), text: content,
               'previous_answer_was_rejected_because': feedback}
    return ModelRequest('REASONING', METHOD_INSTRUCTIONS.format(text=text), context, generation_schema(method_schema(claim_predicate)))


def method_call(response, claim_predicate, content, already_stated, not_yet_stated, *, source_ref, offset, limit, assertion_ref):
    """The ``extract`` call of the model's naming ``response``: ``experiment_types`` are the types named, each once, in the
    order named (an empty list: the window is done without a record). A method that is not one of the class's is rejected
    before any unit exists. No cap on the number named (owner, 2026-11-22; it cannot exceed the types of the class)."""
    schema = method_schema(claim_predicate)
    methods = list(dict.fromkeys(decode_response(response, schema)['methods']))
    for method in methods:
        if method not in schema['properties']['methods']['items']['enum']:
            raise Rejected({'status': 'invalid', 'category': 'method_not_listed', 'detail': method})
    return ToolCall('extract', {'experiment_types': methods, 'claim_predicate': claim_predicate,
                                'source_ref': source_ref, 'chunk': content, 'offset': offset, 'limit': limit,
                                'assertion_ref': assertion_ref, 'already_stated_fields': already_stated,
                                'not_yet_stated_fields': not_yet_stated})


async def extraction_arguments(model, arguments, *, text, reading=''):
    """The arguments of the leaf record of the type named in ``arguments`` (the ``extract`` call of ``method_call``): the
    model (the unit's recorded ``ctx.model``) fills that type's form with its identity block, quote-only; an answer the
    validator refuses is asked again with the reason, until one is accepted."""
    feedback = None
    while True:
        request = extraction_request(arguments['experiment_type'], arguments['chunk'], feedback,
                                     arguments['already_stated_fields'], arguments['not_yet_stated_fields'],
                                     text=text, reading=reading)
        response = await model.complete(request.role, request.instructions, request.context, request.output_schema)
        try:
            return extraction_call(response, arguments['experiment_type'], arguments['chunk'],
                                   source_ref=arguments['source_ref'], offset=arguments['offset'],
                                   limit=arguments['limit'], assertion_ref=arguments['assertion_ref']).arguments
        except Rejected as refused:
            feedback = refused.feedback


def leaf_record(arguments):
    """The leaf record the arguments of an ``extract`` call (``extraction_call``) make: the record of the commissioned type with
    the identity keys beside ``source_ref`` and ``experiment_type``. Its experiment ref is ``kind:source:offset-end`` of the
    window. Pure: the episode holds it."""
    kind = arguments['experiment_type']
    window = str(arguments['offset']) + '-' + str(arguments['offset'] + arguments['limit'])
    record = FORMS[kind].record_from_answer(arguments['answer'], arguments['chunk'], arguments['offset'],
                                            kind + ':' + arguments['source_ref'] + ':' + window,
                                            arguments['source_ref'], arguments['assertion_ref'])
    return identity.with_identity(record, arguments['identity'], arguments['chunk'], arguments['offset'])


def field_counts(records, record_refs):
    """{'stated', 'newly_stated', 'asked'} over the held leaf records ``record_refs`` (in the order given, read through the
    custody reader ``records``): ``stated`` adds up what each record states, ``newly_stated`` counts each field once, at the
    first record of its experiment type that states it, ``asked`` is the number of fields the forms asked: the fields of each
    experiment type held, each type once (the same for every record of one type). A field belongs to its type's form, so
    the records of two methods of one text are counted apart and newly_stated never exceeds asked. The field rule is
    ``literature_identity_extraction.stated_fields``."""
    seen, stated, asked = set(), 0, {}
    for ref in record_refs:
        record = json.loads(records.get_artifact(ref))
        kind = record['experiment_type']
        now = identity.stated_fields(record)
        stated += len(now)
        seen.update((kind, name) for name in now)
        asked[kind] = max(asked.get(kind, 0), len(identity.asked_fields(record)))
    return {'stated': stated, 'newly_stated': len(seen), 'asked': sum(asked.values())}


def newly_stated_share(counts):
    """The share of the asked fields the held records newly state (``field_counts``); 0 when nothing was asked. Never
    bounded, clamped or rescaled."""
    return counts['newly_stated'] / counts['asked'] if counts['asked'] else 0.0


# The source record's field holding the artifact of each representation the page can commission (the source record's
# custody keys: artifact_ref the original bytes, text_ref the text projection, stdout_ref and stderr_ref the retained streams).
ARTIFACT_FIELD = {'original': 'artifact_ref', 'text': 'text_ref', 'stdout': 'stdout_ref', 'stderr': 'stderr_ref'}


def representation_content(records, source_ref, representation):
    """The bytes of the artifact of ``representation`` of the source ``source_ref``, read through the custody reader
    ``records``. A source without that representation fails (``literature_source_representation_unavailable``)."""
    artifact = records.get(source_ref).get(ARTIFACT_FIELD[representation])
    if artifact is None:
        raise LookupError('literature_source_representation_unavailable:' + representation)
    return records.get_artifact(artifact)


def extraction_state(records, outcomes, window_start=None):
    """Where the extraction stands, from the units' ``outcomes`` (read through the custody reader ``records``): the held leaf
    records (``held_record_refs``, a ref held twice is one record), the records that stand (``record_refs``: one per experiment
    ref, ``one_record_per_experiment``; a re-extraction supersedes, it is not merged), the ``counts`` of the fields of every
    held record (``field_counts``), and what the standing records already state and leave unstated (the fields shown to the
    model so a further extraction is not a blind repeat). With ``window_start`` only the standing records of the window that
    starts there are shown."""
    order = [ref for unit in outcomes for ref in unit['outcome']['record_refs']]   # one record per method named; a window with no method holds none
    held_refs = list(dict.fromkeys(order))   # content-addressed: the same answer holds the same record
    held = {ref: json.loads(records.get_artifact(ref)) for ref in held_refs}
    standing = identity.one_record_per_experiment([(ref, held[ref]) for ref in order])
    shown = [held[ref] for ref in standing if window_start is None or held[ref]['span_start'] == window_start]
    already = sorted({name for record in shown for name in identity.stated_fields(record)})
    not_yet = sorted({name for record in shown for name in identity.asked_fields(record)} - set(already))
    return {'held_record_refs': held_refs, 'record_refs': standing, 'counts': field_counts(records, held_refs),
            'named_methods': [name for unit in outcomes for name in unit['outcome']['experiment_types']],
            'already_stated_fields': already, 'not_yet_stated_fields': not_yet}
